args.new_string:
export function Cart({ items, discount }: { items: Item[]; discount?: number }) {
  const total = items.reduce((acc, i) => acc + i.cents, 0);
  const discountedTotal = discount ? total * (1 - discount / 100) : total;
  const discountAmount = discount ? Math.round(total * discount / 100) : 0;

  return (
    <ul>
      {items.map((i) => (
        <li key={i.name}>
          {i.name} — {formatPrice(i.cents)}
        </li>
      ))}
      {discount && discount > 0 && (
        <li>Descuento: -{formatPrice(discountAmount)}</li>
      )}
      <li>Total: {formatPrice(discountedTotal)}</li>
    </ul>
  );
}

